  private final Backend backend;
  private final boolean realMongo;

  MongoPersonTest(MongoDatabase database) {
    this.backend = new BackendResource(database).backend();
    this.realMongo = Single.fromPublisher(database.runCommand(BsonDocument.parse("{buildInfo:1}")))
            .map(bson -> bson.containsKey("gitVersion") && bson.containsKey("version"))
            .onErrorReturn(error -> false)
            .blockingGet();
  }

  @Override
  protected Set<Feature> features() {
    EnumSet<Feature> features = EnumSet.of(Feature.DELETE,
            Feature.QUERY,
            Feature.QUERY_WITH_LIMIT,
            Feature.QUERY_WITH_PROJECTION,
            Feature.QUERY_WITH_OFFSET,
            Feature.ORDER_BY,
            Feature.REGEX,
            Feature.STRING_EMPTY,
            Feature.STRING_PREFIX_SUFFIX,
            Feature.ITERABLE_SIZE,
            Feature.ITERABLE_CONTAINS,
            Feature.ITERABLE_ANY,
            Feature.STRING_LENGTH
    );
    if (realMongo) {
      features.add(Feature.ITERABLE_QUANTIFIERS);
    }
    return features;
  }

  @Override
  protected Backend backend() {
    return backend;
  }
