    this.check(this.repository().find(this.person.pets.any().with(pet -> pet.name.is("fluffy").and(pet.type.not(t -> t.is(Pet.PetType.gecko).or().is(Pet.PetType.panda)))))).toList(Person::fullName).isOf("Emma");
